    """Tính lại "điểm gốc" cho VĐV đã có dữ liệu sẵn, theo đúng định nghĩa:
    điểm gốc = điểm khởi tạo +/- điểm Quản trị viên sửa tay
             = rating hiện tại - (tổng delta từ các trận đấu) - (tổng delta từ thưởng thành tích)
    (suy ra từ: rating hiện tại = điểm khởi tạo + tổng mọi delta đã từng ghi nhận trong lịch sử điểm,
    và lịch sử điểm chỉ có 3 loại: gắn với trận đấu, gắn với thành tích, hoặc Quản trị viên sửa tay —
    xem ranking/services.py để biết 3 nguồn ghi PointHistory.)"""
    Player = apps.get_model("ranking", "Player")
    PointHistory = apps.get_model("ranking", "PointHistory")
    for player in Player.objects.all():
        match_sum = PointHistory.objects.filter(player=player, match__isnull=False).aggregate(s=Sum("delta"))["s"] or 0
        result_sum = PointHistory.objects.filter(player=player, result__isnull=False).aggregate(s=Sum("delta"))["s"] or 0
        player.base_rating = player.rating - match_sum - result_sum
        player.save(update_fields=["base_rating"])


